package com.trampolim.api.future;
import java.util.*;
import java.time.*;
import static com.trampolim.api.future.FutureModel.*;
import static com.trampolim.api.radar.RadarModel.*;
import com.trampolim.api.radar.*;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.server.ResponseStatusException;
@Service
public class FutureTalentService {
 private final JdbcTemplate jdbc;private final RadarBridge bridge;private final SkillCatalog skills;private final RadarService radar;private final TransactionTemplate tx;
 public FutureTalentService(@Qualifier("jdbcTemplate")JdbcTemplate jdbc,RadarBridge bridge,SkillCatalog skills,RadarService radar,@Qualifier("oportunidadesTransactionManager")PlatformTransactionManager manager){this.jdbc=jdbc;this.bridge=bridge;this.skills=skills;this.radar=radar;tx=new TransactionTemplate(manager);}
 public Demand demand(long id){if(id<1)bad("Previsão inválida.");return bridge.convert(bridge.get("/public/companies/future-demands/"+id),Demand.class);}
 public Map<String,Object> browse(String email,long before,int limit,String q,String region,String modality){skills.user(email);if(before<1||limit<1||limit>50)bad("Use páginas de até 50 previsões.");text(q,120);text(region,180);text(modality,40);return bridge.convert(bridge.get("/public/companies/future-demands?before="+before+"&limit="+limit+"&q="+encode(q)+"&region="+encode(region)+"&modality="+encode(modality)),Map.class);}
 private String encode(String value){return java.net.URLEncoder.encode(value,java.nio.charset.StandardCharsets.UTF_8);}
 public List<Map<String,Object>> interests(String email){return jdbc.queryForList("SELECT i.id,i.demand_id,i.occupation,i.area,i.notify,i.consent_at,s.score,s.ready,s.checked_at,s.requirements_revision,(SELECT count(*) FROM future_training_plans p WHERE p.interest_id=i.id AND p.status='IN_PROGRESS') AS plans_started FROM future_talent_interests i LEFT JOIN future_preparation_snapshots s ON s.interest_id=i.id WHERE i.user_id=? ORDER BY i.id DESC LIMIT 200",skills.user(email));}
 public void interest(String email,long id,Interest input){long uid=skills.user(email);if(input==null||!input.consent())bad("Autorize sua participação nos indicadores agregados; nenhum perfil será enviado à empresa.");var demand=demand(id);tx.executeWithoutResult(status->{jdbc.queryForObject("SELECT id FROM app_users WHERE id=? FOR UPDATE",Long.class,uid);if(jdbc.queryForObject("SELECT count(*) FROM future_talent_interests WHERE user_id=?",Integer.class,uid)>=200&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM future_talent_interests WHERE user_id=? AND demand_id=?)",Boolean.class,uid,id)))throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Limite de interesses atingido. Retire interesses antigos.");jdbc.update("INSERT INTO future_talent_interests(user_id,demand_id,occupation,area,notify) VALUES (?,?,?,?,?) ON CONFLICT(user_id,demand_id) DO UPDATE SET occupation=EXCLUDED.occupation,area=EXCLUDED.area,notify=EXCLUDED.notify,consent_at=CURRENT_TIMESTAMP",uid,id,demand.occupation(),demand.area(),input.notifyVacancies());audit(uid,"FUTURE_INTEREST_CONSENTED");});}
 public void withdraw(String email,long id){long uid=skills.user(email);tx.executeWithoutResult(status->{jdbc.update("DELETE FROM future_talent_interests WHERE user_id=? AND demand_id=?",uid,id);jdbc.update("DELETE FROM future_talent_notifications WHERE user_id=? AND demand_id=?",uid,id);jdbc.update("DELETE FROM radar_match_cache WHERE user_id=? AND source='future' AND job_id=?",uid,id);audit(uid,"FUTURE_INTEREST_WITHDRAWN");});}
 private void audit(long uid,String event){jdbc.update("INSERT INTO future_talent_audit(actor_id,event) VALUES (?,?)",uid,event);}
 public Map<String,Object> prepare(String email,long id){long uid=skills.user(email);Demand d=demand(id);var result=new LinkedHashMap<String,Object>(radar.matchFuture(email,new Job("future",id,d.occupation(),d.company(),d.area(),d.region(),d.modality(),d.educationDescription()+"\n"+d.experienceDescription(),d.requirements(),d.updatedAt())));result.put("demand",d);var interests=jdbc.queryForList("SELECT id FROM future_talent_interests WHERE user_id=? AND demand_id=?",uid,id);result.put("interested",!interests.isEmpty());
  if(!interests.isEmpty()&&!"UNAVAILABLE".equals(result.get("evidenceStatus"))){long interest=((Number)interests.get(0).get("id")).longValue();var analysis=(Map<String,Object>)result.get("analysis");var gaps=new TreeSet<String>();var met=new TreeSet<String>();var verified=new TreeSet<String>();for(var item:(List<Map<String,Object>>)analysis.get("skills")){String code=item.get("skillCode").toString();if("MET".equals(item.get("status"))){met.add(code);if(((Number)item.get("verifiedLevel")).intValue()>=((Number)item.get("requiredLevel")).intValue())verified.add(code);}else gaps.add(code);}Number score=(Number)analysis.get("score");boolean ready=score!=null&&score.doubleValue()>=80&&((List<?>)analysis.get("eliminatoryNotDemonstrated")).isEmpty()&&((List<?>)analysis.get("pendingInformation")).isEmpty()&&((List<Map<String,Object>>)analysis.get("skills")).stream().filter(item->Boolean.TRUE.equals(item.get("mandatory"))).allMatch(item->"MET".equals(item.get("status")));int policy=((Number)analysis.get("policyRevision")).intValue();
   tx.executeWithoutResult(status->{// Lock the consent row: withdrawal and snapshots cannot race into recreating data.
    if(jdbc.queryForList("SELECT id FROM future_talent_interests WHERE id=? AND user_id=? FOR UPDATE",interest,uid).isEmpty())return;
    jdbc.update("INSERT INTO future_preparation_snapshots(interest_id,requirements_revision,policy_revision,score,ready,baseline_gaps,gaps,met,verified_met) VALUES (?,?,?,?,?,?::jsonb,?::jsonb,?::jsonb,?::jsonb) ON CONFLICT(interest_id) DO UPDATE SET baseline_gaps=CASE WHEN future_preparation_snapshots.requirements_revision=EXCLUDED.requirements_revision AND future_preparation_snapshots.policy_revision=EXCLUDED.policy_revision THEN future_preparation_snapshots.baseline_gaps ELSE EXCLUDED.baseline_gaps END,requirements_revision=EXCLUDED.requirements_revision,policy_revision=EXCLUDED.policy_revision,score=EXCLUDED.score,ready=EXCLUDED.ready,gaps=EXCLUDED.gaps,met=EXCLUDED.met,verified_met=EXCLUDED.verified_met,checked_at=CURRENT_TIMESTAMP",interest,d.requirements().revision(),policy,score,ready,bridge.encode(gaps),bridge.encode(gaps),bridge.encode(met),bridge.encode(verified));
    jdbc.update("INSERT INTO future_preparation_daily(interest_id,requirements_revision,policy_revision,score,ready,gap_count) VALUES (?,?,?,?,?,?) ON CONFLICT(interest_id,day) DO UPDATE SET requirements_revision=EXCLUDED.requirements_revision,policy_revision=EXCLUDED.policy_revision,score=EXCLUDED.score,ready=EXCLUDED.ready,gap_count=EXCLUDED.gap_count",interest,d.requirements().revision(),policy,score,ready,gaps.size());jdbc.update("DELETE FROM future_preparation_daily WHERE interest_id=? AND day<CURRENT_DATE-90",interest);jdbc.update("UPDATE future_talent_interests SET refresh_after=CURRENT_TIMESTAMP+INTERVAL '1 day' WHERE id=?",interest);
   });
  }
  result.put("progress",jdbc.queryForList("SELECT s.score,s.ready,s.requirements_revision,s.policy_revision,s.checked_at,jsonb_array_length(s.baseline_gaps) AS baseline_gap_count,jsonb_array_length(s.gaps) AS gap_count,(SELECT count(*) FROM jsonb_array_elements_text(s.baseline_gaps) x WHERE NOT s.gaps @> to_jsonb(x.value)) AS resolved_gaps FROM future_preparation_snapshots s JOIN future_talent_interests i ON i.id=s.interest_id WHERE i.user_id=? AND i.demand_id=? AND s.requirements_revision=? AND s.policy_revision=?",uid,id,d.requirements().revision(),((Map<?,?>)result.get("analysis")).get("policyRevision")));return result;
 }
 public void plan(String email,long id,Plan input){long uid=skills.user(email);if(input==null||input.courseId()<1||input.moduleId()<1||!Set.of("IN_PROGRESS","STOPPED").contains(Objects.toString(input.status(),"")))bad("Plano de estudo inválido.");var rows=jdbc.queryForList("SELECT id FROM future_talent_interests WHERE user_id=? AND demand_id=?",uid,id);if(rows.isEmpty())bad("Manifeste interesse antes de iniciar um plano.");long interest=((Number)rows.get(0).get("id")).longValue();String[] titles={"",""};if(input.status().equals("IN_PROGRESS")){var analysis=prepare(email,id);var items=(List<Map<String,Object>>)((Map<?,?>)analysis.get("training")).get("items");var chosen=items.stream().filter(item->((Number)item.get("course_id")).longValue()==input.courseId()&&((Number)item.get("module_id")).longValue()==input.moduleId()).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Use um módulo publicado recomendado para as lacunas atuais."));titles[0]=text(chosen.get("course_title").toString(),180);titles[1]=text(chosen.get("module_title").toString(),180);}
  tx.executeWithoutResult(status->{if(jdbc.queryForList("SELECT id FROM future_talent_interests WHERE id=? AND user_id=? FOR UPDATE",interest,uid).isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"O interesse foi retirado.");if(input.status().equals("STOPPED"))jdbc.update("UPDATE future_training_plans SET status='STOPPED',updated_at=CURRENT_TIMESTAMP WHERE interest_id=? AND course_id=? AND module_id=?",interest,input.courseId(),input.moduleId());else{if(jdbc.queryForObject("SELECT count(*) FROM future_training_plans WHERE interest_id=?",Integer.class,interest)>=40&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM future_training_plans WHERE interest_id=? AND course_id=? AND module_id=?)",Boolean.class,interest,input.courseId(),input.moduleId())))bad("Limite de planos atingido para esta previsão.");jdbc.update("INSERT INTO future_training_plans(interest_id,course_id,module_id,status,course_title,module_title) VALUES (?,?,?,?,?,?) ON CONFLICT(interest_id,course_id,module_id) DO UPDATE SET status=EXCLUDED.status,course_title=EXCLUDED.course_title,module_title=EXCLUDED.module_title,updated_at=CURRENT_TIMESTAMP",interest,input.courseId(),input.moduleId(),input.status(),titles[0],titles[1]);}audit(uid,"FUTURE_STUDY_PLAN_UPDATED");});
 }
 public List<Map<String,Object>> plans(String email,long id){return jdbc.queryForList("SELECT p.course_id,p.module_id,p.course_title,p.module_title,p.status,p.updated_at FROM future_training_plans p JOIN future_talent_interests i ON i.id=p.interest_id WHERE i.user_id=? AND i.demand_id=? ORDER BY p.updated_at DESC LIMIT 40",skills.user(email),id);}
 public Map<String,Object> summary(String key,SummaryRequest input){bridge.authorize(key);if(input==null||input.demandId()<1||input.requirementsRevision()<0)bad("Consulta inválida.");long id=input.demandId();long count=jdbc.queryForObject("SELECT count(*) FROM future_talent_interests WHERE demand_id=?",Long.class,id);var out=new LinkedHashMap<String,Object>();out.put("minimumCohort",5);out.put("interested",FutureModel.band(count));out.put("insufficientSample",count<5);out.put("notice","Somente participantes que autorizaram indicadores agregados. Contagens em faixas de cinco; células pequenas são suprimidas. Preparação compatível exige nota mínima de 80%, todas as competências obrigatórias atendidas e ausência de pendências ou critérios eliminatórios não demonstrados. Não é garantia de contratação.");if(count<5)return out;
  int policy=radar.policy().revision();String where=" FROM future_talent_interests i JOIN future_preparation_snapshots s ON s.interest_id=i.id WHERE i.demand_id=? AND s.requirements_revision=? AND s.policy_revision=? AND s.checked_at>CURRENT_TIMESTAMP-INTERVAL '48 hours'";Object[] args={id,input.requirementsRevision(),policy};var row=jdbc.queryForMap("SELECT count(*) AS assessed,count(*) FILTER(WHERE s.ready) AS ready,count(*) FILTER(WHERE NOT s.ready) AS preparing"+where,args);for(String field:List.of("assessed","ready","preparing"))out.put(field,FutureModel.band(((Number)row.get(field)).longValue()));out.put("trainingStarted",FutureModel.band(jdbc.queryForObject("SELECT count(*) FROM future_talent_interests i WHERE i.demand_id=? AND EXISTS(SELECT 1 FROM future_training_plans p WHERE p.interest_id=i.id AND p.status='IN_PROGRESS')",Long.class,id)));out.put("trainingNotice","Plano iniciado por declaração do candidato; não equivale a matrícula ou conclusão comprovada no Capacita.");
  for(String column:List.of("gaps","met","verified_met")){var rows=jdbc.queryForList("SELECT x.value AS skill_code,count(*) AS contributors"+where.replace(" WHERE "," CROSS JOIN LATERAL jsonb_array_elements_text(s."+column+") x WHERE ")+" GROUP BY x.value HAVING count(*)>=5 ORDER BY count(*) DESC,x.value LIMIT 40",args);List<Map<String,Object>> safe=new ArrayList<>();for(var item:rows)safe.add(Map.of("skillCode",item.get("skill_code"),"count",FutureModel.band(((Number)item.get("contributors")).longValue())));out.put(column,safe);}
  long resolvedPeople=jdbc.queryForObject("SELECT count(*)"+where+" AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(s.baseline_gaps) x WHERE NOT s.gaps @> to_jsonb(x.value))",Long.class,args);out.put("peopleWithResolvedGaps",FutureModel.band(resolvedPeople));out.put("gapNotice","Lacunas resolvidas são comparadas dentro da mesma revisão de requisitos e pesos; podem decorrer de declaração revisada ou comprovação autorizada. Competências comprovadas aparecem separadamente.");
  var days=jdbc.queryForList("SELECT h.day,count(*) AS assessed,count(*) FILTER(WHERE h.ready) AS ready FROM future_preparation_daily h JOIN future_talent_interests i ON i.id=h.interest_id WHERE i.demand_id=? AND h.requirements_revision=? AND h.policy_revision=? AND h.day>=CURRENT_DATE-30 GROUP BY h.day HAVING count(*)>=5 ORDER BY h.day",args);out.put("evolution",days.stream().map(day->Map.of("day",day.get("day").toString(),"assessed",FutureModel.band(((Number)day.get("assessed")).longValue()),"ready",FutureModel.band(((Number)day.get("ready")).longValue()))).toList());out.put("freshnessHours",48);out.put("requirementsRevision",input.requirementsRevision());out.put("policyRevision",policy);return out;
 }
 public Map<String,Object> notifications(String email,long before,int limit){long uid=skills.user(email);if(before<1||limit<1||limit>50)bad("Consulta inválida.");var rows=jdbc.queryForList("SELECT id,demand_id,listing_id,title,read_at,created_at FROM future_talent_notifications WHERE user_id=? AND id<? ORDER BY id DESC LIMIT ?",uid,before,limit+1);var result=new LinkedHashMap<String,Object>();result.put("items",rows.stream().limit(limit).toList());result.put("nextCursor",rows.size()>limit?rows.get(limit-1).get("id"):null);result.put("unreadCount",jdbc.queryForObject("SELECT count(*) FROM future_talent_notifications WHERE user_id=? AND read_at IS NULL",Long.class,uid));return result;}
 public void read(String email,long id){if(jdbc.update("UPDATE future_talent_notifications SET read_at=COALESCE(read_at,CURRENT_TIMESTAMP) WHERE id=? AND user_id=?",id,skills.user(email))==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);}
 public Map<String,Object> vacancy(String email,long id){skills.user(email);return bridge.convert(bridge.get("/public/companies/future-vacancies/"+id),Map.class);}
 public Map<String,Object> export(String email){long uid=jdbc.queryForObject("SELECT id FROM app_users WHERE LOWER(email)=LOWER(?)",Long.class,email);return Map.of("interests",jdbc.queryForList("SELECT demand_id,occupation,area,consent_at,notify,created_at FROM future_talent_interests WHERE user_id=?",uid),"snapshots",exportSnapshots(uid),"history",jdbc.queryForList("SELECT h.* FROM future_preparation_daily h JOIN future_talent_interests i ON i.id=h.interest_id WHERE i.user_id=?",uid),"plans",jdbc.queryForList("SELECT p.* FROM future_training_plans p JOIN future_talent_interests i ON i.id=p.interest_id WHERE i.user_id=?",uid),"notifications",jdbc.queryForList("SELECT demand_id,listing_id,title,read_at,created_at FROM future_talent_notifications WHERE user_id=?",uid));}
 private List<Map<String,Object>> exportSnapshots(long uid){var rows=jdbc.queryForList("SELECT s.* FROM future_preparation_snapshots s JOIN future_talent_interests i ON i.id=s.interest_id WHERE i.user_id=?",uid);for(var row:rows)for(String field:List.of("baseline_gaps","gaps","met","verified_met"))row.put(field,bridge.convert(bridge.read(row.get(field)),List.class));return rows;}
 // Bounded durable polling: no profile or candidate identity leaves this data store.
 public void pollVacancies(){tx.executeWithoutResult(status->{var state=jdbc.queryForList("SELECT cursor FROM future_delivery_state WHERE id=1 FOR UPDATE SKIP LOCKED");if(state.isEmpty())return;long cursor=((Number)state.get(0).get("cursor")).longValue();var feed=bridge.get("/public/companies/future-job-events?after="+cursor+"&limit=100");for(var event:feed.path("items")){jdbc.update("INSERT INTO future_notification_jobs(event_id,demand_id,listing_id,title,published_at) VALUES (?,?,?,?,?) ON CONFLICT DO NOTHING",event.path("event_id").asLong(),event.path("demand_id").asLong(),event.path("listing_id").asLong(),text(event.path("title").asText(),180),java.sql.Timestamp.from(Instant.parse(event.path("published_at").asText())));}long next=feed.path("nextCursor").asLong(cursor);if(next<cursor)throw new IllegalStateException("Cursor inválido da integração.");jdbc.update("UPDATE future_delivery_state SET cursor=? WHERE id=1",next);});}
 public void deliverBatch(){tx.executeWithoutResult(status->{var jobs=jdbc.queryForList("SELECT * FROM future_notification_jobs WHERE completed=FALSE ORDER BY event_id FOR UPDATE SKIP LOCKED LIMIT 1");if(jobs.isEmpty())return;var job=jobs.get(0);long event=((Number)job.get("event_id")).longValue();try{bridge.get("/public/companies/radar-jobs/"+job.get("listing_id"));}catch(ResponseStatusException error){if(error.getStatusCode().value()==404){jdbc.update("UPDATE future_notification_jobs SET completed=TRUE WHERE event_id=?",event);return;}throw error;}
   var users=jdbc.queryForList("SELECT i.user_id FROM future_talent_interests i JOIN app_users u ON u.id=i.user_id WHERE i.demand_id=? AND i.user_id>? AND i.notify=TRUE AND i.created_at<=? AND u.email_verified=TRUE AND u.account_type='PERSON' ORDER BY i.user_id LIMIT 500 FOR UPDATE OF i",job.get("demand_id"),job.get("cursor_user"),job.get("published_at"));for(var user:users)jdbc.update("INSERT INTO future_talent_notifications(user_id,demand_id,listing_id,title) VALUES (?,?,?,?) ON CONFLICT DO NOTHING",user.get("user_id"),job.get("demand_id"),job.get("listing_id"),job.get("title"));long end=users.isEmpty()?((Number)job.get("cursor_user")).longValue():((Number)users.get(users.size()-1).get("user_id")).longValue();jdbc.update("UPDATE future_notification_jobs SET cursor_user=?,completed=? WHERE event_id=?",end,users.size()<500,event);
  });}
 public void cleanup(){jdbc.update("DELETE FROM future_preparation_daily WHERE (interest_id,day) IN (SELECT interest_id,day FROM future_preparation_daily WHERE day<CURRENT_DATE-90 ORDER BY day,interest_id LIMIT 1000)");}
 public void refreshBatch(){var rows=tx.execute(status->jdbc.queryForList("WITH batch AS (SELECT i.id FROM future_talent_interests i JOIN app_users eligible ON eligible.id=i.user_id AND eligible.email_verified=TRUE AND eligible.account_type='PERSON' WHERE i.refresh_after<CURRENT_TIMESTAMP ORDER BY i.refresh_after,i.id LIMIT 20 FOR UPDATE OF i SKIP LOCKED) UPDATE future_talent_interests i SET refresh_after=CURRENT_TIMESTAMP+INTERVAL '1 day' FROM batch,app_users u WHERE i.id=batch.id AND u.id=i.user_id AND u.email_verified=TRUE RETURNING i.demand_id,u.email"));for(var row:rows){if(Thread.currentThread().isInterrupted())return;try{prepare(row.get("email").toString(),((Number)row.get("demand_id")).longValue());}catch(ResponseStatusException ignored){/* Unavailable, suspended or expired sources never generate invented progress. */}}}
}
